/**
 * Out-of-office rows. Every read and write is filtered by `orgId`; there is at most one row per member per organization.
 *
 * Must call (do not reimplement): orgPredicate
 */
import { and, eq } from "drizzle-orm";
import { getDb, memberAbsences } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toMemberAbsence } from "./_mappers";
import type { OrgId, UserId } from "@/types/common";
import type { MemberAbsence } from "@/types/member";

export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .get();
  return row ? toMemberAbsence(row) : null;
}

/** Stores the absence, replacing whatever the member had set before. */
export async function upsertAbsence(
  absence: MemberAbsence,
): Promise<MemberAbsence> {
  const row = getDb()
    .insert(memberAbsences)
    .values({
      orgId: absence.orgId,
      userId: absence.userId,
      delegateUserId: absence.delegateUserId,
      startsAt: absence.startsAt,
      endsAt: absence.endsAt,
      note: absence.note,
    })
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: {
        delegateUserId: absence.delegateUserId,
        startsAt: absence.startsAt,
        endsAt: absence.endsAt,
        note: absence.note,
      },
    })
    .returning()
    .get();
  return toMemberAbsence(row);
}

export async function deleteAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .run();
}

/** Drops every absence that names `delegateUserId`; the absences themselves stay. */
export async function clearDelegation(
  orgId: OrgId,
  delegateUserId: UserId,
): Promise<void> {
  getDb()
    .update(memberAbsences)
    .set({ delegateUserId: null })
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.delegateUserId, delegateUserId),
      ),
    )
    .run();
}

