describe("alerts while away", () => {
  it("sends the overdue alert to the delegate, not the assignee", async () => {
    const tenant = await createTenant("absence-overdue", "growth");
    await memberService.setAbsence(
      tenant.actors.admin,
      absenceInput(tenant.org.id, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
      }),
    );
    await usageRepo.recomputeUsage(tenant.org.id);

    const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const issue = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late while away",
        assigneeId: tenant.userIds.member,
        dueAt: PAST_DUE,
      }),
      tenant.userIds.owner,
      number,
    );

    await runOverdueIssueJob(INSIDE);

    const forDelegate = await notificationsFor(tenant, tenant.userIds.admin, "issue_overdue");
    const forAssignee = await notificationsFor(tenant, tenant.userIds.member, "issue_overdue");
    expect(forDelegate.map((row) => row.body)).toEqual([
      expect.stringContaining(issue.id),
    ]);
    expect(forAssignee).toHaveLength(0);

    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stored?.assigneeId).toBe(tenant.userIds.member);
  });

  it("alerts the mentioned member and their delegate once each, with no alert to the author", async () => {
    const tenant = await createTenant("absence-mention", "growth");
    await memberService.setAbsence(
