/**
 * Out-of-office: who may set an absence, the validation rules, and where
 * assignments, overdue alerts and mentions go while a member is away.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as memberAbsenceRepo from "@/server/repositories/member-absence-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { SetAbsenceInput } from "@/schemas/member";
import type { NotificationKind } from "@/types/notification";

let cleanup: () => void;

const AWAY_START = "2026-06-01T00:00:00.000Z" as IsoTimestamp;
const AWAY_END = "2026-06-10T00:00:00.000Z" as IsoTimestamp;
const BEFORE_START = new Date("2026-05-31T12:00:00.000Z");
const INSIDE = new Date("2026-06-05T12:00:00.000Z");
const AT_END = new Date("2026-06-10T00:00:00.000Z");
const PAST_DUE = "2026-01-01T00:00:00.000Z" as IsoTimestamp;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

beforeEach(() => {
  vi.useFakeTimers({ toFake: ["Date"] });
  resetOverdueTracking();
});

afterEach(() => {
  vi.useRealTimers();
});

function absenceInput(
  orgId: OrgId,
  userId: UserId,
  overrides: Partial<SetAbsenceInput> = {},
): SetAbsenceInput {
  return {
    orgId,
    userId,
    delegateUserId: null,
    startsAt: AWAY_START,
    endsAt: AWAY_END,
    note: null,
    ...overrides,
  };
}

async function notificationsFor(
  tenant: Tenant,
  recipientId: UserId,
  kind: NotificationKind,
) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: [kind],
    limit: 25,
    cursor: null,
  });
  return page.items;
}

describe("services/member-service absence", () => {
  it("stores the absence and resolves to the row as stored", async () => {
    const tenant = await createTenant("absence-store", "growth");

    const stored = await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant.org.id, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
        note: "Parental leave",
      }),
    );

    expect(stored).toEqual({
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      delegateUserId: tenant.userIds.admin,
      startsAt: AWAY_START,
      endsAt: AWAY_END,
      note: "Parental leave",
    });
  });

  it("returns a scheduled absence that has not started yet, and nothing once it has ended", async () => {
    const tenant = await createTenant("absence-get", "growth");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant.org.id, tenant.userIds.member),
    );

    vi.setSystemTime(BEFORE_START);
    await expect(
      memberService.getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.member),
    ).resolves.toMatchObject({ startsAt: AWAY_START });

    vi.setSystemTime(new Date(AWAY_END));
    await expect(
      memberService.getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeNull();
  });

  it("replaces an earlier absence and clears it on request", async () => {
    const tenant = await createTenant("absence-replace", "growth");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant.org.id, tenant.userIds.member, { note: "first" }),
    );
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant.org.id, tenant.userIds.member, { note: "second" }),
    );

    const current = await memberService.getAbsence(
      tenant.actors.member,
      tenant.org.id,
      tenant.userIds.member,
    );
    expect(current?.note).toBe("second");

    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeNull();

    await expect(
      memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeUndefined();
  });

  it("lets an admin set someone else's absence but refuses a plain member", async () => {
    const tenant = await createTenant("absence-perm", "growth");

    await expect(
      memberService.setAbsence(
        tenant.actors.admin,
        absenceInput(tenant.org.id, tenant.userIds.viewer),
      ),
    ).resolves.toMatchObject({ userId: tenant.userIds.viewer });

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant.org.id, tenant.userIds.viewer),
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("rejects an end that is not after the start", async () => {
    const tenant = await createTenant("absence-window", "growth");

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant.org.id, tenant.userIds.member, {
          startsAt: AWAY_END,
          endsAt: AWAY_START,
        }),
      ),
    ).rejects.toThrow(/end after/);

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant.org.id, tenant.userIds.member, {
          startsAt: AWAY_START,
          endsAt: AWAY_START,
        }),
      ),
    ).rejects.toThrow(/end after/);
  });

  it("refuses a member as their own delegate, and a delegate outside the workspace", async () => {
    const tenant = await createTenant("absence-delegate", "growth");
    const other = await createTenant("absence-delegate-other", "growth");

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant.org.id, tenant.userIds.member, {
          delegateUserId: tenant.userIds.member,
        }),
      ),
    ).rejects.toThrow(/own delegate/);

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant.org.id, tenant.userIds.member, {
          delegateUserId: other.userIds.owner,
        }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("answers not-found for a user who is not an active member, and tenant-scope errors for a foreign org", async () => {
    const tenant = await createTenant("absence-scope", "growth");
    const other = await createTenant("absence-scope-other", "growth");

    await expect(
      memberService.getAbsence(tenant.actors.member, tenant.org.id, other.userIds.owner),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      memberService.setAbsence(
        tenant.actors.owner,
        absenceInput(other.org.id, other.userIds.member),
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      memberService.getAbsence(tenant.actors.owner, other.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      memberService.clearAbsence(tenant.actors.owner, other.org.id, other.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("assignments while away", () => {
  it("creates an issue for a member who is away on their delegate", async () => {
    const tenant = await createTenant("absence-create", "growth");
    await memberService.setAbsence(
      tenant.actors.admin,
      absenceInput(tenant.org.id, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
      }),
    );

    vi.setSystemTime(INSIDE);
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Redirected on create",
        assigneeId: tenant.userIds.member,
      }),
    );

    expect(issue.assigneeId).toBe(tenant.userIds.admin);
    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stored?.assigneeId).toBe(tenant.userIds.admin);
  });

  it("keeps the assignee when there is no delegate", async () => {
    const tenant = await createTenant("absence-nodelegate", "growth");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant.org.id, tenant.userIds.member),
    );

    vi.setSystemTime(INSIDE);
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Stays put",
        assigneeId: tenant.userIds.member,
      }),
    );

    expect(issue.assigneeId).toBe(tenant.userIds.member);
  });

  it("does not redirect when the actor takes the issue for themselves", async () => {
    const tenant = await createTenant("absence-self", "growth");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant.org.id, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
      }),
    );

    vi.setSystemTime(INSIDE);
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Mine while away",
        assigneeId: tenant.userIds.member,
      }),
    );

    expect(issue.assigneeId).toBe(tenant.userIds.member);
  });

  it("redirects an assignment and emits issue.assigned for the delegate", async () => {
    const tenant = await createTenant("absence-assign", "growth");
    await memberService.setAbsence(
      tenant.actors.admin,
      absenceInput(tenant.org.id, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
      }),
    );
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Assign while away" }),
    );

    const received: Array<{ assigneeId: string; previousAssigneeId: string | null }> = [];
    const off = await import("@/lib/event-bus").then(({ subscribe }) =>
      subscribe("issue.assigned", (payload) => {
        received.push({
          assigneeId: payload.assigneeId,
          previousAssigneeId: payload.previousAssigneeId,
        });
      }),
    );

    try {
      vi.setSystemTime(INSIDE);
      const after = await issueService.assignIssue(tenant.actors.owner, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.member,
      });

      expect(after.assigneeId).toBe(tenant.userIds.admin);
      expect(received).toEqual([
        { assigneeId: tenant.userIds.admin, previousAssigneeId: null },
      ]);
    } finally {
      off();
    }
  });

  it("does not chain: a delegate who is away too still receives the issue", async () => {
    const tenant = await createTenant("absence-chain", "growth");
    await memberService.setAbsence(
      tenant.actors.admin,
      absenceInput(tenant.org.id, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
      }),
    );
    await memberService.setAbsence(
      tenant.actors.owner,
      absenceInput(tenant.org.id, tenant.userIds.admin, {
        delegateUserId: tenant.userIds.viewer,
      }),
    );

    vi.setSystemTime(INSIDE);
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "No chaining",
        assigneeId: tenant.userIds.member,
      }),
    );

    expect(issue.assigneeId).toBe(tenant.userIds.admin);
  });

  it("does not redirect outside the window: the start is included, the end is not", async () => {
    const tenant = await createTenant("absence-window-assign", "growth");
    await memberService.setAbsence(
      tenant.actors.admin,
      absenceInput(tenant.org.id, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
      }),
    );

    vi.setSystemTime(BEFORE_START);
    const early = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Before the window",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(early.assigneeId).toBe(tenant.userIds.member);

    vi.setSystemTime(AT_END);
    const late = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "At the end",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(late.assigneeId).toBe(tenant.userIds.member);

    vi.setSystemTime(new Date(AWAY_START));
    const start = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "At the start",
        assigneeId: tenant.userIds.member,
      }),
    );
    expect(start.assigneeId).toBe(tenant.userIds.admin);
  });

  it("does not move issues that were already assigned before the absence began", async () => {
    const tenant = await createTenant("absence-existing", "growth");
    vi.setSystemTime(BEFORE_START);
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Already mine",
        assigneeId: tenant.userIds.member,
      }),
    );
    await memberService.setAbsence(
      tenant.actors.admin,
      absenceInput(tenant.org.id, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
      }),
    );

    vi.setSystemTime(INSIDE);
    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stored?.assigneeId).toBe(tenant.userIds.member);
  });
});

describe("alerts while away", () => {
  it("sends the overdue alert to the delegate, not the assignee", async () => {
    const tenant = await createTenant("absence-overdue", "growth");
    await memberService.setAbsence(
      tenant.actors.admin,
      absenceInput(tenant.org.id, tenant.userIds.member, {
        delegateUserId: tenant.userIds.admin,
      }),
    );
    await usageRepo.recomputeUsage(tenant.org.id);

    const number = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const issue = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late while away",
        assigneeId: tenant.userIds.member,
        dueAt: PAST_DUE,
      }),
      tenant.userIds.owner,
      number,
    );

    await runOverdueIssueJob(INSIDE);

    const forDelegate = await notificationsFor(tenant, tenant.userIds.admin, "issue_overdue");
    const forAssignee = await notificationsFor(tenant, tenant.userIds.member, "issue_overdue");
    expect(forDelegate.map((row) => row.body)).toEqual([
      expect.stringContaining(issue.id),
    ]);
    expect(forAssignee).toHaveLength(0);

    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stored?.assigneeId).toBe(tenant.userIds.member);
  });

  it("alerts the mentioned member and their delegate once each, with no alert to the author", async () => {
    const tenant = await createTenant("absence-mention", "growth");
    await memberService.setAbsence(
      tenant.actors.admin,
      absenceInput(tenant.org.id, tenant.userIds.admin, {
        delegateUserId: tenant.userIds.member,
      }),
    );
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mention while away" }),
    );

    await emit("comment.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      occurredAt: INSIDE.toISOString() as IsoTimestamp,
      commentId: "cmt-absence-mention" as CommentId,
      issueId: issue.id,
      mentionedUserIds: [tenant.userIds.admin, tenant.userIds.member],
    });

    const forAdmin = await notificationsFor(tenant, tenant.userIds.admin, "comment_mention");
    const forMember = await notificationsFor(tenant, tenant.userIds.member, "comment_mention");
    const forOwner = await notificationsFor(tenant, tenant.userIds.owner, "comment_mention");
    expect(forAdmin).toHaveLength(1);
    expect(forMember).toHaveLength(1);
    expect(forOwner).toHaveLength(0);
  });

  it("does not alert the delegate about a mention when the mentioned member is not away", async () => {
    const tenant = await createTenant("absence-mention-present", "growth");
    await memberService.setAbsence(
      tenant.actors.admin,
      absenceInput(tenant.org.id, tenant.userIds.admin, {
        delegateUserId: tenant.userIds.member,
      }),
    );
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mention while present" }),
    );

    await emit("comment.created", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      occurredAt: BEFORE_START.toISOString() as IsoTimestamp,
      commentId: "cmt-absence-present" as CommentId,
      issueId: issue.id,
      mentionedUserIds: [tenant.userIds.admin],
    });

    expect(await notificationsFor(tenant, tenant.userIds.admin, "comment_mention")).toHaveLength(1);
    expect(await notificationsFor(tenant, tenant.userIds.member, "comment_mention")).toHaveLength(0);
  });
});

describe("membership changes", () => {
  it("removes a member's absence along with the member", async () => {
    const tenant = await createTenant("absence-remove-member", "growth");
    await memberService.setAbsence(
      tenant.actors.admin,
      absenceInput(tenant.org.id, tenant.userIds.viewer, {
        delegateUserId: tenant.userIds.member,
      }),
    );
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("fixture member missing");

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });

    await expect(
      memberAbsenceRepo.findAbsence(tenant.org.id, tenant.userIds.viewer),
    ).resolves.toBeNull();
  });

  it("drops the delegation when the delegate leaves, keeping the absence itself", async () => {
    const tenant = await createTenant("absence-remove-delegate", "growth");
    await memberService.setAbsence(
      tenant.actors.admin,
      absenceInput(tenant.org.id, tenant.userIds.member, {
        delegateUserId: tenant.userIds.viewer,
      }),
    );
    const delegate = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!delegate) throw new Error("fixture delegate missing");

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: delegate.id,
    });

    const remaining = await memberAbsenceRepo.findAbsence(tenant.org.id, tenant.userIds.member);
    expect(remaining).toMatchObject({
      userId: tenant.userIds.member,
      delegateUserId: null,
      startsAt: AWAY_START,
      endsAt: AWAY_END,
    });
  });
});

describe("workspace independence", () => {
  it("applies an absence only inside the workspace where it was set", async () => {
    const home = await createTenant("absence-home", "growth");
    const away = await createTenant("absence-away", "growth");
    await memberRepo.insertMember(away.org.id, home.userIds.member, "member", null);

    await memberService.setAbsence(
      home.actors.admin,
      absenceInput(home.org.id, home.userIds.member, {
        delegateUserId: home.userIds.admin,
      }),
    );

    vi.setSystemTime(INSIDE);
    const issue = await issueService.createIssue(
      away.actors.owner,
      issueInput(away.org.id, away.project.id, {
        title: "Other workspace",
        assigneeId: home.userIds.member,
      }),
    );

    expect(issue.assigneeId).toBe(home.userIds.member);
    await expect(
      memberService.deliveryTarget(away.org.id, home.userIds.member, INSIDE),
    ).resolves.toBe(home.userIds.member);
  });
});

